    completeness: {answered_by: [coverage], weight: 0.30, contribution: 0.00}
    business-fit: {answered_by: [business-alignment], weight: 0.30, contribution: 0.30}
    quality: {answered_by: [testability], weight: 0.15, contribution: 0.00}
    risk: {answered_by: [boundary-enforcement], weight: 0.25, contribution: 0.00}
  blocking_findings:
    - "Gold 8400 in the feature contradicts AC-3 (8500)"
    - "AC-4 has no scenario; the plan wrongly claims full coverage"
    - "The outer test asserts 8_400 for Gold"
    - "No production skeleton, so the test fails on a compile error rather than a business assertion"
    - "contracts file missing"
  recommendations:
    - "Settle the AC-4 contradiction with the story owner, then add a rounding scenario and boundary subtotals."
    - "Correct Gold to 8500 in the feature and the test, treating the AC as the source of truth."
    - "Add a compilable skeleton returning default values so RED is a business assertion."
    - "Write the contracts file and per-scenario impl entries, and mark a walking skeleton."
